import static org.junit.jupiter.api.Assertions.*;

/** Actual Spring/JPA commit boundaries, physical files and pg_dump/restore against isolated
 * PostgreSQL. No real account, mail, payment provider or native application database is used. */
class PrivacySuppressionConfirmationIT {
    @TempDir Path temporary;private static RealPostgres database;private ServletWebServerApplicationContext app;private JdbcTemplate sql;private Path storage,operations,journalPath;private String[] args;
    private static final byte[] BYTES="%PDF-1.7\nSynthetic orphan evidence\n%%EOF".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    private static final String PASSWORD="Synthetic orphan recovery test password 2026";
    record Gate(CountDownLatch entered,CountDownLatch release,AtomicReference<UUID> file){}
    static class TestStorage extends PrivateFileStorage {
        final AtomicReference<Gate> gate=new AtomicReference<>();final AtomicBoolean failErase=new AtomicBoolean();TestStorage(StorageSettings settings){super(settings);}
        @Override public void put(String key,byte[] data)throws IOException {super.put(key,data);var current=gate.get();if(current!=null){current.file().set(UUID.fromString(key));current.entered().countDown();try{if(!current.release().await(15,TimeUnit.SECONDS))throw new IOException("Synthetic upload gate timeout.");}catch(InterruptedException stopped){Thread.currentThread().interrupt();throw new IOException("Synthetic upload interrupted.");}}}
        @Override public void eraseVerified(String key)throws IOException {if(failErase.get())throw new IOException("Synthetic physical cleanup failure.");super.eraseVerified(key);}
    }
    @TestConfiguration static class StorageConfig {@Bean @Primary TestStorage testPrivateStorage(StorageSettings settings){return new TestStorage(settings);}}
    @BeforeAll static void database(){database=new RealPostgres();}
    @AfterAll static void databaseClose(){if(database!=null)database.close();}
    @AfterEach void close(){if(app!=null){app.close();app=null;}}
    @BeforeEach void setup()throws Exception {
        database.resetSchema();storage=temporary.resolve("files");operations=temporary.resolve("ops");journalPath=temporary.resolve("journal");var values=new ArrayList<>(List.of(AuthTestSettings.arguments(database.apiConnectionUrl())));values.addAll(List.of("--STORAGE_PATH="+storage,"--FRONTEND_PATH="+temporary.resolve("public"),"--PRIVACY_OPERATIONS_ROOT="+operations,"--PRIVACY_ERASURE_JOURNAL_PATH="+journalPath,"--DEV_MAIL_PATH="+temporary.resolve("mail")));args=values.toArray(String[]::new);
        var env=new MockEnvironment();for(String arg:args){int at=arg.indexOf('=');env.withProperty(arg.substring(2,at),arg.substring(at+1));}var json=new ObjectMapper();var crypto=new CryptoService();var auth=new AuthSettings(env);var files=new StorageSettings(env);new PrivacyBackupCatalog(new PrivacyOperationsSettings(env,files),new PrivacySettings(env),new PrivacySigningKeys(env,auth,crypto,json),json,Clock.systemUTC()).initialize();start();
    }
    private void start(){app=(ServletWebServerApplicationContext)new SpringApplicationBuilder(UniCaronaApplication.class,StorageConfig.class).run(args);sql=app.getBean(JdbcTemplate.class);}
    private static String sha(byte[] bytes)throws Exception {return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}
    private UUID orphan()throws Exception {UUID file=UUID.randomUUID();app.getBean(PrivateFileStorage.class).put(file.toString(),BYTES);return file;}
    private PrivacyOrphanFileTransactions tx(){return app.getBean(PrivacyOrphanFileTransactions.class);}
    private void age(UUID file){sql.update("UPDATE privacy_orphan_file_observations SET first_seen_at=now()-interval '2 days',last_seen_at=now()-interval '2 days' WHERE file_id=?",file);}
    private PrivacyErasureJournal journal(){return app.getBean(PrivacyErasureJournal.class);}
    private void guard()throws Exception {app.getBean(PrivacyRestoreGuard.class).run(new DefaultApplicationArguments());}
    private Actor owner(){String hash=app.getBean(CryptoService.class).hashPassword(PASSWORD);UUID id=sql.queryForObject("INSERT INTO users(email,password_hash,name,birth_date,email_verified_at) VALUES(?,?,'Synthetic orphan test owner','2000-01-01',now()) RETURNING id",UUID.class,UUID.randomUUID()+"@example.test",hash);return new Actor(id,"user","active",null,null,null,true,Set.of());}
    private void metadata(UUID file,Actor owner)throws Exception {sql.update("INSERT INTO stored_files(id,owner_id,purpose,storage_key,content_type,byte_size,sha256) VALUES(?,?,'identity',?,'application/pdf',?,?)",file,owner.id(),file.toString(),BYTES.length,sha(BYTES));}
    private PrivacySuppressionConfirmationTransactions confirmations(){return app.getBean(PrivacySuppressionConfirmationTransactions.class);}
    private PrivacyErasureJournal.Entry due(Actor owner)throws Exception {Instant at=Instant.now().minus(Duration.ofDays(80));UUID closure=UUID.randomUUID();journal().ensure(owner.id(),closure,at,at.plus(Duration.ofDays(37)));return journal().entries().stream().filter(e->e.closure().equals(closure)).findFirst().orElseThrow();}
    private UUID requested(Actor owner)throws Exception {UUID file=orphan();metadata(file,owner);sql.update("UPDATE stored_files SET deleted_at=now(),erasure_requested_at=now() WHERE id=?",file);return file;}
    private PrivacyErasureJournal.FileEntry fileEntry(UUID file)throws Exception {return journal().fileEntries().stream().filter(e->e.file().equals(file)).findFirst().orElseThrow();}
    @Test void anExpiredInstructionForAnUnscrubbedAccountNeverBecomesACompletedDeletion()throws Exception {
        var owner=owner();var entry=due(owner);assertEquals(PrivacyErasureJournal.Verification.INCOMPLETE,confirmations().account(entry));assertNull(journal().entries().getFirst().confirmedAt());assertEquals(0,confirmations().retire(100));assertEquals("active",sql.queryForObject("SELECT account_status FROM users WHERE id=?",String.class,owner.id()));assertEquals(0,app.getBean(PrivacyBackupCatalog.class).store().minimumRestorePointEpochMs());
    }
    @Test void failedKnownFileErasureCannotConfirmAndRetryKeepsTheOriginalInstructionDates()throws Exception {
        var owner=owner();UUID file=requested(owner);var controlled=app.getBean(TestStorage.class);controlled.failErase.set(true);assertThrows(IOException.class,()->app.getBean(PrivacyFileErasure.class).erase(file));var pending=fileEntry(file);assertNull(pending.confirmedAt());assertEquals(PrivacyErasureJournal.Verification.INCOMPLETE,confirmations().file(pending));assertTrue(Files.exists(storage.resolve(file.toString())));controlled.failErase.set(false);assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));var confirmed=fileEntry(file);assertNotNull(confirmed.confirmedAt());assertEquals(pending.preparedAt(),confirmed.preparedAt());assertEquals(pending.suppressionUntil(),confirmed.suppressionUntil());assertTrue(sql.queryForObject("SELECT erased_at IS NOT NULL AND sha256='erased' FROM stored_files WHERE id=?",Boolean.class,file));
    }
    @Test void rollbackAfterPhysicalRemovalLeavesAnUnconfirmedInstructionUntilMetadataCommits()throws Exception {
        UUID file=requested(owner());assertThrows(IllegalStateException.class,()->app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{try{assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));}catch(IOException error){throw new java.io.UncheckedIOException(error);}TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void beforeCommit(boolean readOnly){throw new IllegalStateException("Synthetic rollback after physical suppression");}});}));assertFalse(Files.exists(storage.resolve(file.toString())));var pending=fileEntry(file);assertNull(pending.confirmedAt());assertEquals(PrivacyErasureJournal.Verification.INCOMPLETE,confirmations().file(pending));assertNull(sql.queryForObject("SELECT erased_at FROM stored_files WHERE id=?",Timestamp.class,file));assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));assertNotNull(fileEntry(file).confirmedAt());assertEquals(pending.preparedAt(),fileEntry(file).preparedAt());
    }
    @Test void fullAccountSuppressionConfirmsOnlyAfterProfileAndUnheldFilesHaveCommitted()throws Exception {
        var owner=owner();UUID file=requested(owner);var entry=due(owner);app.getBean(TestStorage.class).failErase.set(true);app.getBean(PrivacyErasureMaintenance.class).replay(entry);assertEquals("Conta excluída",sql.queryForObject("SELECT name FROM users WHERE id=?",String.class,owner.id()));assertNull(journal().entries().getFirst().confirmedAt());assertTrue(Files.exists(storage.resolve(file.toString())));app.getBean(TestStorage.class).failErase.set(false);app.getBean(PrivacyErasureMaintenance.class).replay(entry);var completed=journal().entries().getFirst();assertNotNull(completed.confirmedAt());assertFalse(Files.exists(storage.resolve(file.toString())));assertEquals(entry.preparedAt(),completed.preparedAt());assertEquals(entry.suppressionUntil(),completed.suppressionUntil());assertEquals("completed",sql.queryForObject("SELECT status FROM privacy_erasure_tasks WHERE closure_id=?",String.class,entry.closure()));
    }
    @Test void aPartiallyMaskedRestoredProfileIsScrubbedAgainWithoutRenewingItsRetainedIdentity()throws Exception {
        var owner=owner();var entry=due(owner);app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{UUID clearing=sql.queryForObject("INSERT INTO ledger_accounts(kind) VALUES('provider_clearing') RETURNING id",UUID.class),credit=sql.queryForObject("INSERT INTO ledger_accounts(owner_id,kind) VALUES(?,'passenger_credit') RETURNING id",UUID.class,owner.id());UUID transaction=sql.queryForObject("INSERT INTO ledger_transactions(event_key,kind,reason,body_hash) VALUES(?,'synthetic_completion','Synthetic completion preservation',?) RETURNING id",UUID.class,"completion:"+UUID.randomUUID(),"b".repeat(64));sql.update("INSERT INTO ledger_entries(transaction_id,account_id,cents) VALUES(?,?,-700),(?,?,700)",transaction,clearing,transaction,credit);});app.getBean(PrivacyErasureMaintenance.class).replay(entry);var completed=journal().entries().getFirst();assertNotNull(completed.confirmedAt());String retained=sql.queryForObject("SELECT (to_jsonb(p)-'content_ciphertext')::text FROM privacy_retained_records p WHERE user_id=? AND category='contract_identity' AND NOT hold_only",String.class,owner.id());sql.update("UPDATE users SET name='Synthetic restored private name' WHERE id=?",owner.id());assertEquals(PrivacyErasureJournal.Verification.INCOMPLETE,confirmations().account(completed));assertNull(journal().entries().getFirst().confirmedAt());app.getBean(PrivacyErasureMaintenance.class).replay(completed);assertEquals("Conta excluída",sql.queryForObject("SELECT name FROM users WHERE id=?",String.class,owner.id()));assertEquals(retained,sql.queryForObject("SELECT (to_jsonb(p)-'content_ciphertext')::text FROM privacy_retained_records p WHERE user_id=? AND category='contract_identity' AND NOT hold_only",String.class,owner.id()));assertEquals(700L,sql.queryForObject("SELECT sum(e.cents) FROM ledger_entries e JOIN ledger_accounts a ON a.id=e.account_id WHERE a.owner_id=?",Long.class,owner.id()));assertEquals(entry.preparedAt(),journal().entries().getFirst().preparedAt());assertNotNull(journal().entries().getFirst().confirmedAt());
    }
    @Test void confirmedDeletionMustCommitItsDatabaseHorizonBeforeRetirementAndOldArchivesThenFailClosed()throws Exception {
        var owner=owner();Path before=temporary.resolve("before-completion.dump");database.dumpDatabaseArchive(before);var entry=due(owner);app.getBean(PrivacyErasureMaintenance.class).replay(entry);var confirmed=journal().entries().getFirst();assertNotNull(confirmed.confirmedAt());assertEquals(0,confirmations().retire(100));app.getBean(PrivacyRestoreFence.class).markObservedAtLeast(confirmed.confirmedAt());assertEquals(1,confirmations().retire(100));assertTrue(journal().entries().isEmpty());guard();assertTrue(app.getBean(PrivacyReadiness.class).ready());app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(before);assertThrows(Exception.class,this::start);assertNull(app);
    }
    @Test void reintroducedKnownBytesInvalidateTheWitnessAndAreResuppressedWithoutChangingTheDeadline()throws Exception {
        UUID file=requested(owner());assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));var confirmed=fileEntry(file);assertNotNull(confirmed.confirmedAt());Files.write(storage.resolve(file.toString()),BYTES);assertEquals(PrivacyErasureJournal.Verification.INCOMPLETE,confirmations().file(confirmed));assertNull(fileEntry(file).confirmedAt());assertTrue(app.getBean(PrivacyFileErasure.class).suppressRecorded(file));var again=fileEntry(file);assertNotNull(again.confirmedAt());assertEquals(confirmed.preparedAt(),again.preparedAt());assertEquals(confirmed.suppressionUntil(),again.suppressionUntil());guard();assertEquals(again.confirmedAt(),fileEntry(file).confirmedAt(),"Already-clean replay must preserve completion rather than restarting the witness on each boot");
    }
    @Test void staleActorCannotPutAnyFileAfterTheAccountWasDeactivated()throws Exception {
        var owner=owner();sql.update("UPDATE users SET account_status='closing' WHERE id=?",owner.id());assertThrows(com.unicarona.shared.ApiException.class,()->app.getBean(FileService.class).upload(owner,"identity",BYTES));assertFalse(Files.exists(storage));assertTrue(journal().fileEntries().isEmpty());assertEquals(0,sql.queryForObject("SELECT count(*) FROM stored_files",Integer.class));
    }
    @Test void aMaskedUserDoesNotHideRestoredVehicleAndPreciseRouteDataFromReplay()throws Exception {
        var owner=owner();var entry=due(owner);app.getBean(PrivacyErasureMaintenance.class).replay(entry);assertNotNull(journal().entries().getFirst().confirmedAt());UUID university=sql.queryForObject("INSERT INTO universities(slug,name,city,state_code) VALUES(?,'Synthetic campus','Synthetic city','GO') RETURNING id",UUID.class,"synthetic-"+UUID.randomUUID());UUID route=sql.queryForObject("INSERT INTO ride_routes(university_id,driver_id,region,meeting,distance_m,origin_address,origin_lat,origin_lng) VALUES(?,?,'Synthetic restored neighborhood','Synthetic private meeting',12000,'Synthetic restored address',-16.1,-48.1) RETURNING id",UUID.class,university,owner.id());UUID vehicle=sql.queryForObject("INSERT INTO vehicles(owner_id,model,color,plate,capacity,status) VALUES(?,'Synthetic restored car','Black','ABC1D23',4,'pending') RETURNING id",UUID.class,owner.id());assertEquals(PrivacyErasureJournal.Verification.INCOMPLETE,confirmations().account(journal().entries().getFirst()));app.getBean(PrivacyErasureMaintenance.class).replay(entry);assertTrue(sql.queryForObject("SELECT region='Região removida' AND meeting='Detalhes removidos' AND origin_address IS NULL AND origin_lat IS NULL AND origin_lng IS NULL FROM ride_routes WHERE id=?",Boolean.class,route));assertTrue(sql.queryForObject("SELECT model='Veículo indisponível' AND color='Indisponível' AND plate='XXX0X00' AND status='retired' AND deleted_at IS NOT NULL FROM vehicles WHERE id=?",Boolean.class,vehicle));assertNotNull(journal().entries().getFirst().confirmedAt());assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_retained_records WHERE user_id=?",Integer.class,owner.id()));
    }
    @Test void conflictingKnownFileOwnershipBlocksProofAndReadinessWithoutRemovingTheBytes()throws Exception {
        var first=owner();UUID file=requested(first);assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));var entry=fileEntry(file);var other=owner();sql.update("UPDATE stored_files SET owner_id=? WHERE id=?",other.id(),file);Files.write(storage.resolve(file.toString()),BYTES);assertThrows(IOException.class,()->confirmations().file(entry));assertThrows(Exception.class,this::guard);assertFalse(app.getBean(PrivacyReadiness.class).ready());assertArrayEquals(BYTES,Files.readAllBytes(storage.resolve(file.toString())));assertEquals(other.id(),sql.queryForObject("SELECT owner_id FROM stored_files WHERE id=?",UUID.class,file));
    }
    @Test void aCompletedAccountMayPreserveHeldBytesAndReplayErasesThemWhenThatSpecificPurposeEnds()throws Exception {
        var owner=owner();UUID file=requested(owner),hold=UUID.randomUUID();String reason=app.getBean(PrivacyEvidenceCrypto.class).seal(PrivacyEvidenceCrypto.Field.HOLD_REASON,owner.id(),hold,"Synthetic scoped preservation for completion proof");app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{sql.update("INSERT INTO privacy_legal_holds(id,user_id,category,resource_type,resource_id,legal_basis,reason_ciphertext,created_by,review_at,expires_at) VALUES(?,?,'files','stored_file',?,'regular_exercise_of_rights',?,?,now()+interval '1 hour',now()+interval '1 day')",hold,owner.id(),file,reason,owner.id());app.getBean(PrivacyHoldRecovery.class).stage();});var entry=due(owner);app.getBean(PrivacyErasureMaintenance.class).replay(entry);var confirmed=journal().entries().getFirst();assertNotNull(confirmed.confirmedAt());assertArrayEquals(BYTES,Files.readAllBytes(storage.resolve(file.toString())));assertTrue(sql.queryForObject("SELECT deleted_at IS NOT NULL AND erasure_requested_at IS NOT NULL AND erased_at IS NULL FROM stored_files WHERE id=?",Boolean.class,file));guard();assertArrayEquals(BYTES,Files.readAllBytes(storage.resolve(file.toString())));app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{sql.update("UPDATE privacy_legal_holds SET released_at=now() WHERE id=?",hold);app.getBean(PrivacyHoldRecovery.class).stage();});guard();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertFalse(Files.exists(storage.resolve(file.toString())));assertNotNull(journal().entries().getFirst().confirmedAt());assertEquals(entry.preparedAt(),journal().entries().getFirst().preparedAt());assertEquals(entry.suppressionUntil(),journal().entries().getFirst().suppressionUntil());
    }
    @Test void aLockedAccountIsDeferredWithoutGuessingCompletionFromAnEmptySkipLockedResult()throws Exception {
        var owner=owner();var entry=due(owner);app.getBean(PrivacyErasureMaintenance.class).replay(entry);var locked=new CountDownLatch(1);var release=new CountDownLatch(1);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){
            var writer=executor.submit(()->app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{sql.queryForList("SELECT id FROM users WHERE id=? FOR UPDATE",owner.id());locked.countDown();try{if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("Synthetic owner lock gate expired");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException("Synthetic lock interrupted");}}));try{assertTrue(locked.await(8,TimeUnit.SECONDS));assertEquals(PrivacyErasureJournal.Verification.BUSY,confirmations().account(journal().entries().getFirst()));}finally{release.countDown();}writer.get(8,TimeUnit.SECONDS);assertEquals(PrivacyErasureJournal.Verification.COMPLETE,confirmations().account(journal().entries().getFirst()));
        }finally{release.countDown();}
    }
    @Test void ordinaryMaintenanceCanResolveAnExactlyMatchingCommittedControlDuringItsCallbackGap()throws Exception {
        UUID file=orphan();var committed=new CountDownLatch(1);var release=new CountDownLatch(1);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){
            var writer=executor.submit(()->app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public int getOrder(){return Integer.MIN_VALUE;}@Override public void afterCommit(){committed.countDown();try{if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("Synthetic callback gate expired");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException("Synthetic callback gate interrupted");}}});app.getBean(PrivacyHoldRecovery.class).stage();}));
            try{assertTrue(committed.await(8,TimeUnit.SECONDS));assertTrue(app.getBean(PrivacyHoldControlTransactions.class).marker().pending());assertTrue(app.getBean(PrivacyHoldControlJournal.class).pending().isPresent());assertTrue(app.getBean(PrivacyReadiness.class).ready());assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file));assertFalse(app.getBean(PrivacyHoldControlTransactions.class).marker().pending());assertTrue(app.getBean(PrivacyHoldControlJournal.class).pending().isEmpty());assertTrue(app.getBean(PrivacyReadiness.class).ready());}finally{release.countDown();}writer.get(8,TimeUnit.SECONDS);assertTrue(app.getBean(PrivacyReadiness.class).ready());
        }finally{release.countDown();}
    }
}
